            is DateInterval.LastDays -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`days`, buf)
                Unit
            }
            is DateInterval.LastWeeks -> {
                buf.putInt(3)
                FfiConverterUInt.write(value.`weeks`, buf)
